/// <summary>
///CB434, Create Costing price for Base price calculated
/// </summary>
[ExtensionOf(classStr(GUPBasePriceCalcUpdateItem))]
internal final class METGUPBasePriceCalcUpdateItem_Extension
{
    private GUPItemBasePriceCalcTable   itemBasePriceCalcTableLoc;

}

Method.Source:
/// <summary>
/// getting private parameter in the extension 
/// </summary>
/// <param name = "_basePriceCalcTable">
/// record of GUPItemBasePriceCalcTable to calculate base/cost price
/// </param>
public void initFromBuffer(GUPItemBasePriceCalcTable _basePriceCalcTable)
{
    next initFromBuffer(_basePriceCalcTable);
    itemBasePriceCalcTableLoc = _basePriceCalcTable;
}

    /// <summary>
    /// creating cost price
    /// </summary>
    public void run()
    {
        #OCCRetryCount
        try
        {
            ttsbegin;
            next run();
            
            if (this.parmCostPriceTransfer())
            {
                this.createActiveCostVersion();
            }
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            throw error("@SYS18447");
        }

    }

    /// <summary>
    /// separated the finding for the Base price to create cost price based on
    /// </summary>
    private void createActiveCostVersion()
    {
        InventItemPrice             inventItemPrice;
        GUPItemBasePrice            itemBasePrice;
        GUPItemBasePriceCalcTrans   itemBasePriceCalcTrans;
        GUPItemBasePriceCurrentActive itemBasePriceCurrentActive;
        GUPParameters               gupParameters = GUPParameters::find();

        RecordInsertList inventItemPriceInsertList = new RecordInsertList(tableNum(InventItemPrice));

        //looking for GUPItemBasePrice created during the calculation in standard method activateItemBasePriceDirectly
        while select minof(CalculatedPrice) from itemBasePriceCalcTrans
            group by FromDate, ToDate, CreatedDateTime desc
                where itemBasePriceCalcTrans.PriceCalcId == itemBasePriceCalcTableLoc.PriceCalcId &&
                      itemBasePriceCalcTrans.FinalPrice  == NoYes::Yes &&
                      itemBasePriceCalcTrans.PriceType   == GUPBasePriceType::BasePriceInventoryCost
        {
            if (itemBasePriceCalcTrans)
            {
                GUPItemBasePriceCalcTrans itemBasePriceCalcTransLocal = GUPItemBasePriceCalcTrans::findByFinalPrice(
                    itemBasePriceCalcTableLoc.PriceCalcId,
                    GUPBasePriceType::BasePriceInventoryCost,
                    itemBasePriceCalcTrans.CalculatedPrice,
                    itemBasePriceCalcTrans.FromDate,
                    itemBasePriceCalcTrans.ToDate,
                    itemBasePriceCalcTrans.CreatedDateTime);

                while select itemBasePrice
                    where itemBasePrice.PriceCalcId == itemBasePriceCalcTableLoc.PriceCalcId
                        && itemBasePrice.PriceType  == GUPBasePriceType::BasePriceInventoryCost
                        && itemBasePrice.ItemId     == itemBasePriceCalcTableLoc.ItemId
                        && itemBasePrice.InventDimId == itemBasePriceCalcTableLoc.InventDimId
                        && itemBasePrice.FromDate   == itemBasePriceCalcTransLocal.FromDate
                        && itemBasePrice.ToDate     == itemBasePriceCalcTransLocal.ToDate
                join itemBasePriceCurrentActive
                    where itemBasePrice.ItemId == itemBasePriceCurrentActive.ItemId
                    &&  itemBasePrice.InventDimId == itemBasePriceCurrentActive.InventDimId
                    &&  itemBasePrice.PriceType == itemBasePriceCurrentActive.PriceType
                    &&  itemBasePrice.CreatedDateTime == itemBasePriceCurrentActive.MaxCreatedDateTime
                {
                    inventItemPrice.clear();
                    inventItemPrice.ItemId              = itemBasePrice.ItemId;
                    inventItemPrice.initFromInventTableModule(InventTableModule::find(itemBasePrice.ItemId, ModuleInventPurchSales::Invent));
                    inventItemPrice.VersionId           = gupParameters.METCostingVersionId;
                    inventItemPrice.initFromCostingVersion();          
                    inventItemPrice.InventDimId         = itemBasePrice.InventDimId;
                    inventItemPrice.PriceType           = CostingVersionPriceType::Cost;
                    inventItemPrice.PriceQty            = 1;
                    inventItemPrice.Price               = itemBasePrice.Price;
                    inventItemPrice.PriceCalcId         = itemBasePrice.PriceCalcId;
                    inventItemPrice.ActivationDate      = CostingVersion::find(inventItemPrice.VersionId).LastActivation;
                    inventItemPrice.LastPriceUniquenessAllowance = newGuid();

                    inventItemPriceInsertList.add(inventItemPrice);
                }
            }
        }
        inventItemPriceInsertList.insertDatabase();
    }
